          "ru": "Патрик Франциска родился 11 июня 1992 года в Бенсхайме (Германия), так что в ноябре 2026 года ему 34 года. Он до сих пор выступает на международных турнирах: в 2026 году дошёл до финала WTT Champions в Монпелье."
