          "ru": "По странице Butterfly на 18.12.2025, Мива Харимото играет основанием Harimoto Tomokazu Innerforce Super ALC, накладкой Dignics 09C на форхенде и Dignics 05 на бэкхенде. Предыдущая запись, на 11.10.2025, — Dignics 05 с двух сторон."
