          "ru": "По данным Butterfly на 18.12.2025 — Dignics 09C на форхенде и Dignics 05 на бэкхенде. В предыдущих записях с 2021 года на форхенде значился Dignics 05, а на 18.06.2025 — Zyre 03; на бэкхенде — Dignics 05, кроме записи на 18.04.2024 с Dignics 09C."
