    "faq": [
      {
        "q": {
          "ua": "На чому грає Томокадзу Харімото?",
          "ru": "Чем играет Томокадзу Харимото?"
        },
        "a": {
          "ua": "За сторінкою Butterfly станом на 11.10.2025, Томокадзу Харімото грає основою Harimoto Tomokazu Innerforce Super ALC і накладками Zyre 03 з обох боків. До цього, станом на 18.06.2025, у нього був Dignics 05 на форхенді та Zyre 03 на бекхенді.",
          "ru": "По странице Butterfly на 11.10.2025, Томокадзу Харимото играет основанием Harimoto Tomokazu Innerforce Super ALC и накладками Zyre 03 с двух сторон. До этого, на 18.06.2025, у него был Dignics 05 на форхенде и Zyre 03 на бэкхенде."
        }
      },
      {
        "q": {
          "ua": "Яка основа в Харімото?",
          "ru": "Какое основание у Харимото?"
        },
        "a": {
          "ua": "Харімото грає іменною основою Harimoto Tomokazu Innerforce Super ALC: волокно Super ALC у ній розташоване ближче до ядра (inner). Butterfly вказує її станом на 29.08.2024, 18.06.2025 і 11.10.2025; раніше, станом на 09.07.2021, він грав Harimoto Tomokazu Innerforce ALC.",
          "ru": "Харимото играет именным основанием Harimoto Tomokazu Innerforce Super ALC: волокно Super ALC в нём расположено ближе к ядру (inner). Butterfly указывает его на 29.08.2024, 18.06.2025 и 11.10.2025; раньше, на 09.07.2021, он играл Harimoto Tomokazu Innerforce ALC."
        }
      },
      {
        "q": {
          "ua": "Які накладки в Харімото?",
          "ru": "Какие накладки у Харимото?"
        },
        "a": {
          "ua": "Станом на 11.10.2025 Butterfly вказує Zyre 03 і на форхенді, і на бекхенді. У записах станом на 09.07.2021 і 29.08.2024 на сторінці Butterfly значився Dignics 05 з обох боків, а станом на 18.06.2025 — Dignics 05 на форхенді й Zyre 03 на бекхенді.",
          "ru": "По данным Butterfly на 11.10.2025 — Zyre 03 и на форхенде, и на бэкхенде. В записях на 09.07.2021 и 29.08.2024 на странице Butterfly значился Dignics 05 с двух сторон, а на 18.06.2025 — Dignics 05 на форхенде и Zyre 03 на бэкхенде."
        }
      },
      {
        "q": {
          "ua": "Скільки років Томокадзу Харімото?",
          "ru": "Сколько лет Томокадзу Харимото?"
        },
        "a": {
          "ua": "Томокадзу Харімото народився 27 червня 2003 року в Сендаї, Японія. Станом на листопад 2026 року йому 23 роки.",
          "ru": "Томокадзу Харимото родился 27 июня 2003 года в Сендае, Япония. На ноябрь 2026 года ему 23 года."
        }
      },
      {
        "q": {
          "ua": "Яке найвище місце Харімото у світовому рейтингу?",
          "ru": "Какое самое высокое место Харимото в мировом рейтинге?"
        },
        "a": {
          "ua": "Найвище місце Томокадзу Харімото у світовому рейтингу ITTF — 2-ге, у рейтингу 47-го тижня 2022 року (листопад 2022). Того ж року він виграв Кубок Азії в одиночному розряді.",
          "ru": "Самое высокое место Томокадзу Харимото в мировом рейтинге ITTF — 2-е, в рейтинге 47-й недели 2022 года (ноябрь 2022). В том же году он выиграл Кубок Азии в одиночном разряде."
        }
      },
      {
        "q": {
          "ua": "Чи можна купити ракетку Харімото?",
          "ru": "Можно ли купить ракетку Харимото?"
        },
        "a": {
          "ua": "Так, основа Harimoto Tomokazu Innerforce Super ALC і накладка Zyre 03, які Butterfly вказує в його інвентарі, є в каталозі TT Max. Ракетку складають з основи та двох накладок — для набору як у Харімото потрібні дві Zyre 03.",
          "ru": "Да, основание Harimoto Tomokazu Innerforce Super ALC и накладка Zyre 03, которые Butterfly указывает в его инвентаре, есть в каталоге TT Max. Ракетку собирают из основания и двух накладок — для набора как у Харимото нужны две Zyre 03."
        }
      }
    ],
