        "a": {
          "ua": "Шість: дві срібні (команда, 2008 і 2021) і чотири бронзові (одиночний розряд 2012 і 2021, команда 2012 і 2016). На Іграх 2024 року в Парижі медалі він не здобув.",
          "ru": "Шесть: две серебряные (команда, 2008 и 2021) и четыре бронзовые (одиночный разряд 2012 и 2021, команда 2012 и 2016). На Играх 2024 года в Париже медалей он не завоевал."
        }
