          "ua": "Станом на 19.01.2026 — Timo Boll ALC; цю основу Butterfly вказує щонайменше з 18.01.2024. Раніше, за архівними сторінками Butterfly, він грав спеціально замовленою основою з Arylate Carbon (на 21.11.2023), Zhang Jike ALC (2022) і Viscaria (2019).",
          "ru": "На 19.01.2026 — Timo Boll ALC; это основание Butterfly указывает как минимум с 18.01.2024. Раньше, по архивным страницам Butterfly, он играл основанием на спецзаказ с Arylate Carbon (на 21.11.2023), Zhang Jike ALC (2022) и Viscaria (2019)."
