          "ru": "На 19.01.2026 — Dignics 09C на форхенде и Zyre 03 на бэкхенде. На 21.11.2023, 18.01.2024 и 21.01.2025 Butterfly указывала Dignics 09C с двух сторон, а в 2019 году — Tenergy 05 с двух сторон."
