          "ru": "Butterfly указывает основание для пера на спецзаказ с волокном ALC (Arylate Carbon). В 2021–2022 годах та же позиция на странице значилась как Zhang Jike ALC - CS — версия для пера, которую Butterfly продаёт только за пределами Японии. По состоянию на 15.05.2019 и 14.07.2020 Butterfly тоже указывала основание для пера на спецзаказ с ALC, а на 20.08.2015 — основание Butterfly на спецзаказ с ALC."
