          "ru": "На 06.08.2021 Butterfly указывает Dignics 09C на форхенде и Tenergy 05 Hard на бэкхенде. Раньше Butterfly указывала Tenergy 05 с двух сторон (на 20.08.2015), Tenergy 05 Hard с двух сторон (на 15.05.2019) и Dignics 09C с двух сторон (на 14.07.2020)."
