        "ru": "Основание сделано на спецзаказ: Butterfly указывает только, что это основание с арилат-карбоном (ALC), и в свободной продаже его нет. С 07.04.2025 как минимум до 13.01.2026 Butterfly указывала у Чжу Юйлин серийную Viscaria. В интервью Butterfly в апреле 2025 года Чжу рассказывала, что раньше играла лимитированным ALC-основанием Butterfly, снятым с производства, и до сих пор играет основанием той же конструкции — Viscaria. Butterfly не подписывает стороны; форхенд и бэкхенд указаны по постоянному порядку на страницах Butterfly: основание, форхенд, бэкхенд — он совпадает с её словами в том же интервью."
