          "ru": "На 16.02.2026 — основание на спецзаказ, которое Butterfly описывает только как ALC-основание. До этого, с 07.04.2025 как минимум до 13.01.2026, Butterfly указывала у неё серийную Viscaria. В апрельском интервью 2025 года Чжу говорила, что играет Viscaria — основанием той же конструкции, что и лимитированное ALC-основание, которым она играла раньше."
