          "ru": "Tenergy 05 Hard на форхенде и Dignics 09C на бэкхенде (данные Butterfly на 16.02.2026). По её словам, Tenergy 05 Hard стоит на форхенде с конца 2020 года, а Dignics 09C поставила на бэкхенд вместо Tenergy 05 незадолго до интервью Butterfly в апреле 2025 года."
